import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import { MEDIA_URL } from "src/network/endpoints";
import Tooltip from "@mui/material/Tooltip";

const TableAdditionalFeaturesList = ({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
}) => {
  return (
    <>
      <CustomDataGrid
        loading={loading}
        rowCount={totalCount}
        rows={rows}
        columns={[
          {
            field: "description",
            flex: 1,
            minWidth: 300,
            sortable: false,
            headerName: "Description",
            renderCell: ({ row }) => (
              // <Typography
              //   noWrap
              //   variant="body2"
              //   title={row.descriptions?.map((desc) => desc.text).join(", ")}
              // >
              //   {row.descriptions?.map((desc) => desc.text).join(", ")}
              // </Typography>
              <Box>
                <Typography
                  variant="body2"
                  title={row.descriptions
                    ?.slice(0, 2)
                    .map((desc) => desc.text)
                    .join(", ")}
                >
                  <ul
                    style={{
                      listStyleType: "disc",
                      paddingLeft: "20px",
                      margin: 0,
                    }}
                  >
                    {row.descriptions?.slice(0, 2).map((desc, index) => (
                      <li key={index}>
                        {desc.text.length > 100 ? (
                          <span>{`${desc.text.slice(0, 100)}...`}</span>
                        ) : (
                          <span>{desc.text}</span>
                        )}
                      </li>
                    ))}
                  </ul>
                </Typography>
              </Box>
            ),
          },
          {
            field: "Actions",
            flex: 0,
            minWidth: 170,
            sortable: false,
            headerName: "Actions",
            renderCell: ({ row }) => (
              <Box display="flex" alignItems="center" gap="10px">
                <IconButton
                  size="small"
                  color="primary"
                  variant="outlined"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleEdit(e, row);
                  }}
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  size="small"
                  color="secondary"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleDelete(e, row);
                  }}
                >
                  <DeleteIcon />
                </IconButton>
              </Box>
            ),
          },
        ]}
        currentPage={currentPage}
        pageSize={pageSize}
        setCurrentPage={setCurrentPage}
        setPageSize={setPageSize}
      />
    </>
  );
};

export default TableAdditionalFeaturesList;
